-- challenge chal_quiz_js_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_411', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-4-1' AND is_deleted = false LIMIT 1), 'async-generator-early-exit-quiz', 'What happens when you break out of for await?', 'An async generator walks the order pages and a for await loop stops at the first flagged order. Predict what runs - and what never runs.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_411'), 'Each page holds 100 orders and the first flagged order is o-130 (on page 2):

async function* orders() {
  try {
    for (let page = 1; ; page++) {
      console.log(''fetch'', page);
      const rows = await fetchOrders(page);
      yield* rows;
    }
  } finally {
    console.log(''cleanup'');
  }
}

for await (const order of orders()) {
  if (order.flagged) { console.log(''found'', order.id); break; }
}

What is logged?', 'single_choice'::question_type, 'The generator is pull-based: page 2 is only fetched when the consumer asks for order 101, and nothing is fetched ahead. On break, for await...of calls the iterator''s return() method. The suspended generator resumes at its yield as if a return statement were there, so the finally block runs (''cleanup'') and the loop inside the generator never continues - page 3 is never requested. Without return(), every early exit would leak whatever the finally block was supposed to release.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('fetch 1, fetch 2, found o-130, cleanup', true),
        ('fetch 1, fetch 2, found o-130 - finally only runs when the generator finishes on its own, and break just abandons it.', false),
        ('fetch 1, fetch 2, fetch 3, found o-130, cleanup - the generator prefetches the next page while the loop body runs.', false),
        ('fetch 1, fetch 2, found o-130, then the generator keeps fetching in the background until fetchOrders returns an empty page, then cleanup.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_411'), 'const it = orders(); (the same generator as above). Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'Calling an async generator function only creates the generator object; the body starts on the first next(). for await...of closes the iterator with return() on every abrupt exit of the loop - break, return, or an exception thrown by the loop body. A rejection inside the generator (fetchOrders failing) is not swallowed: next() rejects and the for await loop throws it at the loop. A generator object is a single-use iterator, not a re-iterable collection: two loops over the same object share one cursor position, and once one of them closes it, the other gets nothing more.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Calling orders() runs none of the body yet; the first fetch happens on the first it.next().', true),
        ('for await...of calls it.return() when the loop is left with break, with return, or because the loop body throws.', true),
        ('If fetchOrders rejects inside the generator, the for await loop simply ends as if there were no more orders.', false),
        ('Two separate for await loops over the same it object each receive every order from the beginning.', false)
    ) AS o(option_text, is_correct);

