-- challenge chal_quiz_js_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_431', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-4-3' AND is_deleted = false LIMIT 1), 'bounded-queue-backpressure-quiz', 'What does a full queue do to the producer?', 'A bounded queue is only useful if you know what happens at its edges: when it is full, when it is empty and when it is closed.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_431'), 'The thumbnail step and the uploader are decoupled with a bounded queue. No consumer has started yet:

const queue = createAsyncQueue({ capacity: 2 });
for (const file of files) {           // 5 photos
  const blob = await makeThumbnail(file);
  await queue.push(blob);
  console.log(''queued'', file.name);
}

What happens?', 'single_choice'::question_type, 'push() resolves immediately for the first two thumbnails because the queue has room. The third push() returns a promise that stays pending until a consumer pulls, so the loop is suspended at that await: ''queued'' is logged twice, and the producer stops creating thumbnails. At most three blobs exist - two in the buffer and the one waiting inside the pending push(). That pause is backpressure: memory is bounded by the capacity instead of by the number of files. Nothing is dropped and nothing throws; a full queue is a normal state, not an error.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('All 5 are queued; the queue drops the two oldest thumbnails to stay at capacity 2.', false),
        ('''queued'' is logged twice; the third push() stays pending, so the loop pauses until a consumer pulls - at most three thumbnails exist.', true),
        ('The third push() throws a QUEUE_FULL error, and the loop ends with an unhandled rejection.', false),
        ('All 5 are logged as ''queued'' immediately; capacity only limits how many items a consumer can pull at once.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_431'), 'The user leaves the chat while uploads are still queued, and the app calls queue.close(). Which behaviours make close() safe for a producer/consumer queue? (Select all that apply.)', 'multiple_choice'::question_type, 'Closing means "no new items", not "throw away what was accepted": items already in the queue are still delivered, and consumers see the end of the stream ({ done: true }) only after it is drained - otherwise accepted uploads vanish silently. A consumer waiting on an empty queue must be woken with { done: true }, or its for await loop hangs forever and leaks whatever it holds. A push() after close() is a programming error or a race the producer must learn about, so it should reject rather than drop the item quietly. And the end of the stream is a normal outcome: rejecting pending pulls would force every consumer to treat a clean shutdown as a failure.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Items already in the queue are still delivered; consumers get { done: true } only after the queue has drained.', true),
        ('A consumer that is waiting in pull() on an empty queue is woken with { done: true } instead of waiting forever.', true),
        ('push() after close() resolves quietly and discards the item, so producers never need error handling.', false),
        ('close() rejects every pending pull() with an error, so consumers notice the shutdown faster.', false)
    ) AS o(option_text, is_correct);

