-- challenge chal_quiz_js_522 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_522', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 5 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-5-2' AND is_deleted = false LIMIT 1), 'main-thread-scheduling-quiz', 'Which tool for which work?', 'Three pieces of work on an analytics dashboard compete for the same main thread. Decide how each one should be scheduled.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_522'), 'The "Apply filter" handler does this:

button.addEventListener("click", () => {
  spinner.hidden = false;
  const rows = filterRows(allRows, criteria); // ~400 ms of synchronous work
  renderTable(rows);
  spinner.hidden = true;
});

Users say the button feels dead and the spinner never appears. Why?', 'single_choice'::question_type, 'The browser renders between tasks, not in the middle of one. Showing the spinner only changes the DOM; nothing is painted until the click task finishes, and by then the spinner is hidden again. The whole 400 ms is one long task, so the next frame - the visual response to the click that INP measures - waits for all of it. Show the spinner, yield so a frame can be painted, then do the heavy work in slices.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_522') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('spinner.hidden = false is applied asynchronously by the browser, so it races with filterRows.', false),
        ('The browser only paints after the task ends; the 400 ms task delays the next frame, and by then the spinner is hidden again.', true),
        ('The click event is passive by default, so DOM changes inside it are ignored until the next event.', false),
        ('filterRows runs on a background thread and its result overwrites the spinner state when it returns.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_522'), 'Match the scheduling tool to the work: (1) moving a drag preview so it follows the pointer, (2) sending a batch of analytics events when the page has nothing better to do, (3) computing a 20,000-row pivot table after a click, with the page staying responsive.', 'single_choice'::question_type, 'Visual updates that must land in the next frame belong in requestAnimationFrame, which runs right before the browser paints. Low-value background work suits requestIdleCallback (with a timeout so it eventually runs), which only fires in idle periods. Long, user-requested work should be split into slices that yield back to the main thread - scheduler.yield() where available, otherwise setTimeout/MessageChannel - so input can be handled between slices. A Web Worker is also a good choice for (3) if the data can be moved off the main thread.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_522') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('(1) setTimeout(fn, 16), (2) requestAnimationFrame, (3) one synchronous loop inside requestIdleCallback.', false),
        ('(1) requestAnimationFrame, (2) requestIdleCallback with a timeout, (3) slices that yield with scheduler.yield() or setTimeout.', true),
        ('(1) requestIdleCallback, (2) setInterval every 100 ms, (3) Promise.resolve().then() for each row so it runs asynchronously.', false),
        ('(1) requestAnimationFrame, (2) queueMicrotask, (3) requestAnimationFrame for the whole computation.', false)
    ) AS o(option_text, is_correct);

