ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_531'), 'A chat panel registers and later cleans up a resize handler like this:

window.addEventListener("resize", () => layoutMessages(panel));
// ... when the panel closes:
window.removeEventListener("resize", () => layoutMessages(panel));

After closing and reopening the panel 20 times, layoutMessages runs 21 times per resize event. Why?', 'single_choice'::question_type, 'removeEventListener only removes a listener that matches the one registered: same type, the same function object (compared by identity) and the same capture flag. Each arrow expression creates a brand-new function, so the removal call looks for a listener that was never added and silently does nothing. Every open adds one more listener, and each one keeps panel - and everything it references - alive. Keep a reference to the handler, or register with { signal } and abort the controller on cleanup.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_531') AND order_index = 1)
    RETURNING id
)
