SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('removeEventListener is asynchronous; the listener is removed only after the next resize event.', false),
        ('Each arrow function is a new function object, so the removal does not match the registered listener and removes nothing.', true),
        ('Listeners on window can only be removed with { capture: true }.', false),
        ('The browser deduplicates identical listeners, so the extra calls come from layoutMessages being called recursively.', false)
    ) AS o(option_text, is_correct);

