WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_631'), 'The field-service app flushes its outbox and send() fails. Which of these failures should keep the mutation in the outbox so a later flush sends it again? Select all that apply.', 'multiple_choice'::question_type, 'A 503 and a network TypeError say nothing about the mutation itself - the same request can succeed later, so the edit must stay queued. A TypeError from fetch carries no status code at all; treating unknown errors as transient protects the user''s data, and the worst case is one more attempt. A 422 (invalid data) and a 403 (no longer allowed to edit the job) will fail identically on every retry: keeping them would block every later edit of that record. Report them, park them where the user or support can see them, and move on.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_631') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The API gateway answers 503 Service Unavailable during a deploy.', true),
        ('fetch() rejects with TypeError: Failed to fetch because the van is in a tunnel.', true),
        ('The server answers 422 because the technician entered a negative part quantity.', false),
        ('The server answers 403 because the dispatcher reassigned the job to another technician.', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_js_632 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_js_632', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 6 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-6-3' AND is_deleted = false LIMIT 1), 'outbox-sync-client', 'Build the outbox sync client', 'Implement createSyncClient({ send, maxInFlight }) with enqueue(mutation) and flush(). Coalesce unsent edits of the same record, never touch an entry that was already sent, send one mutation per record at a time and at most maxInFlight records at once, keep transient failures (and everything queued behind them) for the next flush, report permanent ones, and resolve flush() with a summary of what was sent, what failed and what is still pending.', 'open', 'hard'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
