VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632'), 'browser', 2000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632'), 'Unsent edits of the same record are merged into one mutation', '{"maxInFlight":2,"steps":[{"op":"enqueue","id":"m1","recordId":"job-17","patch":{"status":"en-route"}},{"op":"enqueue","id":"m2","recordId":"job-18","patch":{"notes":"Gate code 4411"}},{"op":"enqueue","id":"m3","recordId":"job-17","patch":{"status":"on-site","arrivedAt":"09:40"}},{"op":"flush"},{"op":"flush"}]}', '{"calls":["m1 job-17 {\"status\":\"on-site\",\"arrivedAt\":\"09:40\"}","m2 job-18 {\"notes\":\"Gate code 4411\"}"],"maxConcurrent":2,"sameRecordOverlap":false,"flushes":[{"sent":["m1","m2"],"failed":[],"pending":[]},{"sent":[],"failed":[],"pending":[]}]}', 6, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632'), 'At most maxInFlight records sync at once; a second flush() call joins the first', '{"maxInFlight":2,"durations":{"m1":30},"steps":[{"op":"enqueue","id":"m1","recordId":"job-1","patch":{"status":"done"}},{"op":"enqueue","id":"m2","recordId":"job-2","patch":{"status":"done"}},{"op":"enqueue","id":"m3","recordId":"job-3","patch":{"status":"done"}},{"op":"enqueue","id":"m4","recordId":"job-4","patch":{"status":"done"}},{"op":"enqueue","id":"m5","recordId":"job-5","patch":{"status":"done"}},{"op":"flush","twice":true}]}', '{"calls":["m1 job-1 {\"status\":\"done\"}","m2 job-2 {\"status\":\"done\"}","m3 job-3 {\"status\":\"done\"}","m4 job-4 {\"status\":\"done\"}","m5 job-5 {\"status\":\"done\"}"],"maxConcurrent":2,"sameRecordOverlap":false,"flushes":[{"sent":["m2","m3","m1","m4","m5"],"failed":[],"pending":[]}]}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632'), 'An edit made while its record is syncing waits for that call to finish', '{"maxInFlight":3,"durations":{"m3":4},"steps":[{"op":"enqueue","id":"m1","recordId":"job-7","patch":{"status":"on-site"}},{"op":"enqueue","id":"m3","recordId":"job-8","patch":{"parts":["valve"]}},{"op":"flush","during":[{"at":2,"id":"m2","recordId":"job-7","patch":{"status":"done"}}]}]}', '{"calls":["m1 job-7 {\"status\":\"on-site\"}","m3 job-8 {\"parts\":[\"valve\"]}","m2 job-7 {\"status\":\"done\"}"],"maxConcurrent":2,"sameRecordOverlap":false,"flushes":[{"sent":["m3","m1","m2"],"failed":[],"pending":[]}]}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632'), 'Retryable failures stay queued unchanged; permanent ones are reported', '{"maxInFlight":2,"outcomes":{"m1":["retry","ok"],"m2":["fail"]},"steps":[{"op":"enqueue","id":"m1","recordId":"job-3","patch":{"status":"done","signature":"sig-1"}},{"op":"enqueue","id":"m2","recordId":"job-4","patch":{"notes":"Customer not home"}},{"op":"flush"},{"op":"enqueue","id":"m3","recordId":"job-3","patch":{"status":"invoiced"}},{"op":"flush"}]}', '{"calls":["m1 job-3 {\"status\":\"done\",\"signature\":\"sig-1\"}","m2 job-4 {\"notes\":\"Customer not home\"}","m1 job-3 {\"status\":\"done\",\"signature\":\"sig-1\"}","m3 job-3 {\"status\":\"invoiced\"}"],"maxConcurrent":2,"sameRecordOverlap":false,"flushes":[{"sent":[],"failed":[{"id":"m2","error":"422 Unprocessable Entity"}],"pending":["m1"]},{"sent":["m1","m3"],"failed":[],"pending":[]}]}', 6, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_js_632'), 'An unknown network error keeps the record''s edits; other records still sync', '{"maxInFlight":2,"outcomes":{"m1":["network"]},"durations":{"m3":30},"steps":[{"op":"enqueue","id":"m1","recordId":"job-5","patch":{"status":"en-route"}},{"op":"enqueue","id":"m3","recordId":"job-6","patch":{"notes":"Call ahead"}},{"op":"flush","during":[{"at":5,"id":"m2","recordId":"job-5","patch":{"status":"on-site"}}]}]}', '{"calls":["m1 job-5 {\"status\":\"en-route\"}","m3 job-6 {\"notes\":\"Call ahead\"}"],"maxConcurrent":2,"sameRecordOverlap":false,"flushes":[{"sent":["m3"],"failed":[],"pending":["m1","m2"]}]}', 6, false, true, 5);
