-- challenge chal_quiz_js_633 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_633', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 6 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-6-3' AND is_deleted = false LIMIT 1), 'idempotent-mutation-id-quiz', 'The edit that vanished on retry', 'Mutation ids let the server ignore duplicates. Combine that with a well-meant optimisation and see what happens.', 'open', 'hard'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_633'), 'The server stores every processed mutation id and, when it sees an id again, returns the stored result without applying anything. The client sends m-41 { status: ''done'' } for job-42. The server applies it, but the response is lost in a tunnel, so the client keeps m-41 in the outbox. The technician then captures the customer''s signature, and the client merges { signature: ''sig-9'' } into m-41 because ''it was never confirmed anyway''. On the next flush m-41 is sent again. What is the result?', 'single_choice'::question_type, 'To the server, m-41 is a duplicate: it was processed once, so the stored result is returned and the new payload is never applied. The client removes m-41 as ''sent'' and the signature is lost silently. (A stricter server may reject the reused id because the payload changed - the edit still does not land.) Once a mutation has been sent, its id and content are frozen: new edits must go into a new mutation with a new id, queued behind it. That is also why PATCH being ''usually safe to retry'' is not a guarantee - HTTP does not define PATCH as idempotent; the mutation id is what makes retries safe.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_633') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The server applies the signature, because the payload is different from the first request.', false),
        ('The status is applied a second time and the job''s history shows two ''done'' events.', false),
        ('The signature is never stored: the server treats m-41 as an already-processed duplicate, and the client then drops m-41 as successfully sent.', true),
        ('Nothing goes wrong: PATCH requests are idempotent by definition, so the server merges both versions.', false)
    ) AS o(option_text, is_correct);

-- learners enrolled before these lessons existed
INSERT INTO learning.history (user_id, course_id, module_id, lesson_id)
SELECT r.user_id, r.course_id, m.id, l.id
FROM learning.register r
JOIN course.module m ON m.course_id = r.course_id AND m.is_deleted = false
JOIN course.lesson l ON l.module_id = m.id AND l.is_deleted = false
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND r.is_deleted = false
ON CONFLICT DO NOTHING;
WITH ordered AS (
    SELECT h.user_id, h.lesson_id, h.status,
           row_number() OVER (PARTITION BY h.user_id ORDER BY m.order_index, l.order_index) AS rn
    FROM learning.history h
    JOIN course.lesson l ON l.id = h.lesson_id AND l.is_deleted = false
    JOIN course.module m ON m.id = l.module_id AND m.is_deleted = false
    WHERE h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901')
),
next_lesson AS (
    SELECT DISTINCT ON (o.user_id) o.user_id, o.lesson_id
    FROM ordered o
    WHERE o.status = 'enrolled'
      AND NOT EXISTS (SELECT 1 FROM ordered p WHERE p.user_id = o.user_id AND p.rn < o.rn AND p.status <> 'completed')
    ORDER BY o.user_id, o.rn
)
UPDATE learning.history h
SET status = 'in_progress', updated_at = now()
FROM next_lesson n
JOIN learning.register r ON r.user_id = n.user_id AND r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND r.is_deleted = false AND r.status <> 'enrolled'
WHERE h.user_id = n.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND h.lesson_id = n.lesson_id;
UPDATE learning.register r
SET status = 'in_progress'
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND r.status = 'completed'
  AND EXISTS (SELECT 1 FROM learning.history h WHERE h.user_id = r.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND h.status <> 'completed');

COMMIT;
